import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Project {
  id: string;
  title: string;
  category: string;
  image: string;
  link: string;
  year: string;
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

import { GoogleGenAI, Type } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are the "AI Twin" of a world-class senior developer. 
Your personality is professional, slightly edgy (brutalist vibe), and highly knowledgeable.
You answer questions about web development, UI/UX design, and the portfolio's creator.
The creator's skills include: React, TypeScript, Tailwind, Gemini API, and Creative Coding.
Keep responses concise and impactful.
If asked about contact details, point them to the footer links.
`;

export const getGeminiResponse = async (userPrompt: string, history: { role: 'user' | 'model', text: string }[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      ...history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
      { role: 'user', parts: [{ text: userPrompt }] }
    ],
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.7,
      topP: 0.95,
      maxOutputTokens: 500,
    },
  });

  return response.text;
};

