import React, { useState, useEffect } from 'react';
import { Project } from '../types';

interface ProjectCardProps {
  project: Project;
}

const ProjectCard: React.FC<ProjectCardProps> = ({ project }) => {
  const [currentIdx, setCurrentIdx] = useState(0);
  const hasSlideshow = project.images && project.images.length > 0;

  useEffect(() => {
    if (!hasSlideshow) return;

    const interval = setInterval(() => {
      setCurrentIdx((prev) => (prev + 1) % project.images!.length);
    }, 3000); // 3 second rotation

    return () => clearInterval(interval);
  }, [hasSlideshow, project.images]);

  return (
    <a 
      href={project.link} 
      className="group block bg-surface border border-border overflow-hidden transition-all duration-300 hover:border-acid hover:-translate-y-2 h-[450px] flex flex-col"
    >
      <div className="h-[75%] overflow-hidden border-b border-border relative">
        {hasSlideshow ? (
          project.images!.map((img, idx) => (
            <img 
              key={idx}
              src={img} 
              alt={`${project.title} slide ${idx}`} 
              className={`absolute inset-0 w-full h-full object-cover grayscale transition-opacity duration-1000 ease-in-out group-hover:grayscale-0 group-hover:scale-105 ${
                idx === currentIdx ? 'opacity-100' : 'opacity-0'
              }`}
            />
          ))
        ) : (
          <img 
            src={project.image} 
            alt={project.title} 
            className="w-full h-full object-cover grayscale transition-all duration-500 group-hover:grayscale-0 group-hover:scale-105"
          />
        )}

        {/* Slideshow Indicator */}
        {hasSlideshow && (
          <div className="absolute bottom-4 left-4 flex gap-1 z-10">
            {project.images!.map((_, idx) => (
              <div 
                key={idx}
                className={`h-1 transition-all duration-300 ${idx === currentIdx ? 'w-6 bg-acid' : 'w-2 bg-white/30'}`}
              />
            ))}
          </div>
