import React, { useState, useEffect } from 'react';

const CustomCursor: React.FC = () => {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isHovering, setIsHovering] = useState(false);
  const [isClicking, setIsClicking] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const onMouseMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
      if (!isVisible) setIsVisible(true);
    };

    const onMouseDown = () => setIsClicking(true);
    const onMouseUp = () => setIsClicking(false);

    const onMouseOver = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const isInteractable = 
        target.tagName === 'BUTTON' || 
        target.tagName === 'A' || 
        target.closest('button') || 
        target.closest('a') ||
        target.classList.contains('cursor-pointer') ||
        target.closest('.cursor-pointer');

      setIsHovering(!!isInteractable);
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mousedown', onMouseDown);
    window.addEventListener('mouseup', onMouseUp);
    window.addEventListener('mouseover', onMouseOver);

    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('mouseup', onMouseUp);
      window.removeEventListener('mouseover', onMouseOver);
    };
  }, [isVisible]);

  if (!isVisible) return null;

  return (
    <div className="fixed inset-0 pointer-events-none z-[9999] hidden md:block">
      {/* Main Dot */}
      <div 
        className={`fixed w-1.5 h-1.5 bg-acid rounded-full transition-transform duration-75 ease-out transform -translate-x-1/2 -translate-y-1/2 ${
          isClicking ? 'scale-75' : 'scale-100'
        }`}
        style={{ left: `${position.x}px`, top: `${position.y}px` }}
      />

      {/* Follower Ring */}
      <div 
        className={`fixed w-8 h-8 border border-acid/50 rounded-full transition-all duration-300 ease-out transform -translate-x-1/2 -translate-y-1/2 ${
          isHovering ? 'scale-[2.5] bg-acid/10 border-acid' : 'scale-100'
        } ${isClicking ? 'scale-90' : ''}`}
        style={{ 
          left: `${position.x}px`, 
          top: `${position.y}px`,
          transitionProperty: 'transform, width, height, border-color, background-color'
        }}
      />

      {/* Crosshair Lines (Optional Minimalist Brutalist Touch) */}
      {isHovering && (
        <div 
          className="fixed transition-opacity duration-300"
          style={{ left: `${position.x}px`, top: `${position.y}px` }}
        >
          <div className="absolute w-[1px] h-4 bg-acid -top-6 left-0 -translate-x-1/2" />
          <div className="absolute w-[1px] h-4 bg-acid -bottom-6 left-0 -translate-x-1/2" />
          <div className="absolute h-[1px] w-4 bg-acid -left-6 top-0 -translate-y-1/2" />
          <div className="absolute h-[1px] w-4 bg-acid -right-6 top-0 -translate-y-1/2" />
        </div>
      )}
    </div>
  );
};

