const CustomCursor: React.FC = () => {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [hoverType, setHoverType] = useState<string | null>(null);
  const [isClicking, setIsClicking] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const onMouseMove = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });
      if (!isVisible) setIsVisible(true);
    };

    const onMouseDown = () => setIsClicking(true);
    const onMouseUp = () => setIsClicking(false);

    const onMouseOver = (e: MouseEvent) => {
      const target = e.target as HTMLElement;

      const isProject = target.closest('.group.block');
      const isButton = target.tagName === 'BUTTON' || target.closest('button');
      const isLink = target.tagName === 'A' || target.closest('a');

      if (isProject) {
        setHoverType('PROJECT');
      } else if (isButton || isLink) {
        setHoverType('ACTION');
      } else {
        setHoverType(null);
      }
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mousedown', onMouseDown);
    window.addEventListener('mouseup', onMouseUp);
    window.addEventListener('mouseover', onMouseOver);

    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('mouseup', onMouseUp);
      window.removeEventListener('mouseover', onMouseOver);
    };
  }, [isVisible]);

  if (!isVisible) return null;

  const isHovering = !!hoverType;

  return (
    <div className="fixed inset-0 pointer-events-none z-[9999] hidden md:block">
      {/* Precision Core Dot */}
      <div 
        className={`fixed w-1 h-1 bg-acid rounded-full transition-transform duration-100 ease-out transform -translate-x-1/2 -translate-y-1/2 ${
          isClicking ? 'scale-150' : 'scale-100'
        }`}
        style={{ left: `${position.x}px`, top: `${position.y}px` }}
      />

      {/* Outer Interface Ring */}
      <div 
        className={`fixed border border-acid/40 rounded-full transition-all duration-500 ease-out transform -translate-x-1/2 -translate-y-1/2 ${
          isHovering 
            ? 'w-16 h-16 bg-acid/5 border-acid scale-100 rotate-90' 
            : 'w-8 h-8 scale-100 rotate-0'
        } ${isClicking ? 'scale-75 opacity-50' : ''}`}
        style={{ 
          left: `${position.x}px`, 
          top: `${position.y}px`,
        }}
      />

      {/* Brutalist Crosshair Hooks */}
      <div 
        className={`fixed transition-all duration-300 transform -translate-x-1/2 -translate-y-1/2 ${
          isHovering ? 'opacity-100 scale-100' : 'opacity-0 scale-50'
        }`}
        style={{ left: `${position.x}px`, top: `${position.y}px` }}
      >
        {/* The "Something Else" - A precision crosshair instead of a hand */}
        <div className="absolute w-[1px] h-3 bg-acid -top-8 left-1/2 -translate-x-1/2" />
        <div className="absolute w-[1px] h-3 bg-acid -bottom-8 left-1/2 -translate-x-1/2" />
        <div className="absolute h-[1px] w-3 bg-acid -left-8 top-1/2 -translate-y-1/2" />
        <div className="absolute h-[1px] w-3 bg-acid -right-8 top-1/2 -translate-y-1/2" />

        {/* Dynamic Data Label */}
        {hoverType && (
          <div className="absolute top-10 left-1/2 -translate-x-1/2 font-mono text-[8px] font-bold text-acid tracking-[0.3em] whitespace-nowrap bg-bg/80 px-1">
            {hoverType === 'PROJECT' ? 'ACCESS_DATA' : 'EXECUTE'}
          </div>
        )}
      </div>

      {/* Trailing Coordinates (Optional aesthetic touch) */}
      <div 
        className="fixed font-mono text-[6px] text-acid/20 uppercase tracking-tighter"
        style={{ left: `${position.x + 20}px`, top: `${position.y + 20}px` }}
      >
        X:{Math.round(position.x)} Y:{Math.round(position.y)}
      </div>
    </div>
  );
};

