import React, { useState, useEffect, useRef } from 'react';

const CustomCursor: React.FC = () => {
  const dotRef = useRef<HTMLDivElement>(null);
  const ringRef = useRef<HTMLDivElement>(null);
  const crosshairRef = useRef<HTMLDivElement>(null);
  const coordsRef = useRef<HTMLDivElement>(null);

  const mousePos = useRef({ x: 0, y: 0 });
  const ringPos = useRef({ x: 0, y: 0 });
  const [hoverType, setHoverType] = useState<string | null>(null);
  const [isClicking, setIsClicking] = useState(false);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const onMouseMove = (e: MouseEvent) => {
      mousePos.current = { x: e.clientX, y: y: e.clientY };
      if (!isVisible) setIsVisible(true);
    };

    const onMouseDown = () => setIsClicking(true);
    const onMouseUp = () => setIsClicking(false);

    const onMouseOver = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      const isProject = target.closest('.group.block');
      const isButton = target.tagName === 'BUTTON' || target.closest('button');
      const isLink = target.tagName === 'A' || target.closest('a');

      if (isProject) {
        setHoverType('PROJECT');
      } else if (isButton || isLink) {
        setHoverType('ACTION');
      } else {
        setHoverType(null);
      }
    };

    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mousedown', onMouseDown);
    window.addEventListener('mouseup', onMouseUp);
    window.addEventListener('mouseover', onMouseOver);

    // Animation Loop for Smooth Movement
    let animationFrameId: number;
    const render = () => {
      // 1:1 tracking for the core dot
      if (dotRef.current) {
        dotRef.current.style.transform = `translate3d(${mousePos.current.x}px, ${mousePos.current.y}px, 0) translate(-50%, -50%)`;
      }

      // Smooth Lerp (Linear Interpolation) for the ring and crosshair
      // This makes the 'lag' feel like smooth fluid motion rather than stuttering
      const lerpAmount = 0.15; // Adjusted for buttery feel
      ringPos.current.x += (mousePos.current.x - ringPos.current.x) * lerpAmount;
      ringPos.current.y += (mousePos.current.y - ringPos.current.y) * lerpAmount;

      if (ringRef.current) {
        ringRef.current.style.transform = `translate3d(${ringPos.current.x}px, ${ringPos.current.y}px, 0) translate(-50%, -50%)`;
      }
      if (crosshairRef.current) {
        crosshairRef.current.style.transform = `translate3d(${ringPos.current.x}px, ${ringPos.current.y}px, 0) translate(-50%, -50%)`;
      }
      if (coordsRef.current) {
        coordsRef.current.style.transform = `translate3d(${mousePos.current.x + 20}px, ${mousePos.current.y + 20}px, 0)`;
        coordsRef.current.innerText = `X:${Math.round(mousePos.current.x)} Y:${Math.round(mousePos.current.y)}`;
      }

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('mouseup', onMouseUp);
      window.removeEventListener('mouseover', onMouseOver);
      cancelAnimationFrame(animationFrameId);
    };
  }, [isVisible]);

  if (!isVisible) return null;

  const isHovering = !!hoverType;

  return (
    <div className="fixed inset-0 pointer-events-none z-[9999] hidden md:block overflow-hidden">
      {/* Precision Core Dot (1:1 Tracking) */}
      <div 
        ref={dotRef}
        className={`fixed top-0 left-0 w-1 h-1 bg-acid rounded-full transition-transform duration-150 ease-out ${
          isClicking ? 'scale-[2.5]' : 'scale-100'
        }`}
      />

      {/* Outer Interface Ring (Fluid Trailing) */}
      <div 
        ref={ringRef}
        className={`fixed top-0 left-0 border border-acid/40 rounded-full transition-all duration-500 ease-out ${
          isHovering 
            ? 'w-16 h-16 bg-acid/5 border-acid rotate-90' 
            : 'w-8 h-8 rotate-0'
        } ${isClicking ? 'opacity-30 scale-75' : 'opacity-100 scale-100'}`}
      />

      {/* Brutalist Crosshair Hooks (Fluid Trailing) */}
      <div 
        ref={crosshairRef}
        className={`fixed top-0 left-0 transition-opacity duration-300 ${
          isHovering ? 'opacity-100' : 'opacity-0'
        }`}
      >
        <div className="absolute w-[1px] h-3 bg-acid -top-8 left-1/2 -translate-x-1/2" />
        <div className="absolute w-[1px] h-3 bg-acid -bottom-8 left-1/2 -translate-x-1/2" />
        <div className="absolute h-[1px] w-3 bg-acid -left-8 top-1/2 -translate-y-1/2" />
        <div className="absolute h-[1px] w-3 bg-acid -right-8 top-1/2 -translate-y-1/2" />

        {/* Dynamic Data Label */}
        {hoverType && (
          <div className="absolute top-10 left-1/2 -translate-x-1/2 font-mono text-[8px] font-bold text-acid tracking-[0.3em] whitespace-nowrap bg-bg/80 px-1 border border-acid/20 py-0.5">
            {hoverType === 'PROJECT' ? 'ACCESS_DATA' : 'EXECUTE'}
          </div>
