import React, { useEffect, useState, useRef } from 'react';
import { Project } from '../types';

interface ProjectDetailProps {
  project: Project;
  onBack: () => void;
}

const ProjectDetail: React.FC<ProjectDetailProps> = ({ project, onBack }) => {
  const [loadedIndices, setLoadedIndices] = useState<Set<number>>(new Set());
  const [scrollY, setScrollY] = useState(0);
  const footerRef = useRef<HTMLDivElement>(null);
  const [footerVisible, setFooterVisible] = useState(false);

  useEffect(() => {
    window.scrollTo(0, 0);

    const handleScroll = () => {
      setScrollY(window.scrollY);
    };

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) setFooterVisible(true);
      },
      { threshold: 0.1 }
    );

    if (footerRef.current) observer.observe(footerRef.current);
    window.addEventListener('scroll', handleScroll, { passive: true });

    return () => {
      window.removeEventListener('scroll', handleScroll);
      observer.disconnect();
    };
  }, []);

  const allImages = project.images && project.images.length > 0 ? project.images : [project.image];

  const handleMediaLoad = (idx: number) => {
    setLoadedIndices(prev => new Set(prev).add(idx));
  };

  const isVideo = (url: string) => url.toLowerCase().endsWith('.mp4');

  return (
    <div className="min-h-screen bg-bg text-white relative">
      {/* Entry Scanning Effect Overlay */}
      <div className="fixed inset-0 z-[100] bg-acid pointer-events-none animate-out fade-out slide-out-to-top-full duration-700 ease-in-out fill-mode-forwards" />

      {/* Detail Header */}
      <div className="sticky top-0 z-50 bg-bg/80 backdrop-blur-xl border-b border-border p-4 md:p-6 flex justify-between items-center transition-all duration-500">
        <div className="animate-in slide-in-from-left duration-700 ease-out">
          <button 
            onClick={onBack}
            className="group flex items-center gap-2 font-mono text-[10px] uppercase tracking-widest text-acid hover:text-white transition-all active:scale-95"
          >
            <span className="text-xl transition-transform group-hover:-translate-x-1">←</span> 
            <span className="hidden sm:inline">VOL_BACK_TO_ARCHIVE</span>
            <span className="sm:hidden">BACK</span>
          </button>
        </div>
        <div className="text-right animate-in slide-in-from-right duration-700 ease-out">
