          <p className="font-mono text-[8px] md:text-[9px] text-text-sec uppercase mt-1 tracking-[0.3em]">ID_{project.id} // {project.year}</p>
        </div>
      </div>

      {/* Hero Reveal Section */}
      <div className="w-full max-w-screen-2xl mx-auto px-0 md:px-6 pt-8 md:pt-16 pb-32">
        <div className="space-y-12 md:space-y-32">
          {allImages.map((url, idx) => {
            const containerRef = useRef<HTMLDivElement>(null);
            // Parallax calculation: shift image based on scroll relative to its position
            const parallaxOffset = typeof window !== 'undefined' ? (scrollY * 0.1) : 0;

            return (
              <div 
                key={idx} 
                ref={containerRef}
                className="group overflow-hidden bg-[#080808] border-y md:border border-border relative animate-in fade-in slide-in-from-bottom-24 duration-1000 ease-out fill-mode-backwards"
                style={{ animationDelay: `${idx * 150}ms` }}
              >
                {/* Image Label Overlay */}
                <div className="absolute top-4 left-4 z-10 font-mono text-[8px] text-white/20 bg-black/40 px-2 py-1 border border-white/10 uppercase tracking-widest opacity-0 group-hover:opacity-100 transition-opacity duration-500">
                  PLATE_0{idx + 1} // OFFSET: {Math.round(parallaxOffset)}PX
                </div>

                {!loadedIndices.has(idx) && (
                  <div className="absolute inset-0 bg-[#0a0a0a] flex items-center justify-center z-20">
                    <div className="w-8 h-[1px] bg-acid/30 animate-pulse"></div>
                  </div>
                )}

                <div 
                  className="transition-transform duration-100 ease-out will-change-transform"
                  style={{ transform: `translateY(${parallaxOffset % 40}px) scale(1.05)` }}
                >
                  {isVideo(url) ? (
                    <video 
                      src={url} 
                      autoPlay 
                      muted 
                      loop 
                      playsInline
                      onLoadedData={() => handleMediaLoad(idx)}
                      className={`w-full h-auto block mx-auto transition-opacity duration-1000 ${loadedIndices.has(idx) ? 'opacity-100' : 'opacity-0'}`}
                    />
                  ) : (
                    <img 
                      src={url} 
                      alt={`${project.title} - ${idx + 1}`} 
                      loading={idx === 0 ? "eager" : "lazy"}
                      onLoad={() => handleMediaLoad(idx)}
                      className={`w-full h-auto block mx-auto transition-opacity duration-1000 ${loadedIndices.has(idx) ? 'opacity-100' : 'opacity-0'}`}
                      style={{ imageRendering: 'auto' }}
                    />
                  )}
                </div>

                {/* Technical HUD corner markings */}
                <div className="absolute top-0 right-0 w-8 h-8 border-t border-r border-acid/0 group-hover:border-acid/40 transition-colors duration-500" />
                <div className="absolute bottom-0 left-0 w-8 h-8 border-b border-l border-acid/0 group-hover:border-acid/40 transition-colors duration-500" />
              </div>
            );
          })}
        </div>

        {/* Coordinated Footer Reveal */}
        <div 
          ref={footerRef}
          className={`pt-48 pb-32 px-6 text-center transition-all duration-1000 ease-out transform ${
            footerVisible ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-24'
          }`}
        >
          <div className="inline-flex items-center gap-4 mb-8">
            <div className="w-12 h-[1px] bg-border"></div>
