            <div className="w-12 h-[1px] bg-border"></div>
          </div>

          <h2 className="text-5xl md:text-[120px] font-extrabold uppercase tracking-tighter leading-none mb-10">
            {project.title.split(' ')[0]} <br />
            <span className="text-acid">{project.title.split(' ')[1] || 'ARCHIVE'}</span>
          </h2>

          <p className="font-mono text-sm md:text-xl text-text-sec leading-relaxed max-w-2xl mx-auto mb-16">
            This study explores the synergy between digital abstraction and functional communication. 
            All visual assets were meticulously curated to ensure 100% brand coherence.
          </p>

          <button 
