import { GoogleGenAI, Type } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are the "AI Twin" of Omkar, a world-class Visual Communication Designer and Creative Director. 
Your personality is professional, slightly edgy (brutalist vibe), and highly knowledgeable about design theory and technology.
You answer questions about visual design, branding, UI/UX, typography, and Omkar's portfolio.
Omkar's creative software expertise includes: Photoshop, Illustrator, InDesign, After Effects, Fresco, Sketch Pro, and Blender.
His design philosophy focuses on the intersection of bold aesthetics and functional communication.
Keep responses concise, impactful, and "design-forward".
If asked about contact details, point them to the Behance, Instagram, or Email links in the footer.
`;

export const getGeminiResponse = async (userPrompt: string, history: { role: 'user' | 'model', text: string }[]) => {
  // Always use process.env.API_KEY directly for initialization
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [
      ...history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
      { role: 'user', parts: [{ text: userPrompt }] }
    ],
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      temperature: 0.7,
      topP: 0.95,
      // When maxOutputTokens is set, thinkingBudget must also be set for Gemini 3/2.5 models
      maxOutputTokens: 500,
      thinkingConfig: { thinkingBudget: 100 },
    },
  });

  return response.text;
};

